{"implementation":"import math
def solve(case):
    matrix = case["matrix"]
    if not matrix or not all(isinstance(row, list) for row in matrix):
        raise ValueError("Invalid matrix structure")
    nrows = len(matrix)
    if nrows == 0:
        raise ValueError("Empty matrix")
    ncols = len(matrix[0])
    for row in matrix:
        if len(row) != ncols:
            raise ValueError("Inconsistent row lengths")
    idf = []
    for j in range(ncols):
        doc_freq = sum(1 for i in range(nrows) if matrix[i][j] != 0)
        idf_val = math.log(1 + nrows / (1 + doc_freq))
        idf.append(idf_val)
    weighted_matrix = []
    row_degree = []
    for i in range(nrows):
        weighted_row = []
        sum_row = 0.0
        for j in range(ncols):
            val = matrix[i][j] * idf[j]
            weighted_row.append(val)
            sum_row += val
        weighted_matrix.append(weighted_row)
        row_degree.append(sum_row)
    return {"idf": idf, "row_degree": row_degree, "weighted_matrix": weighted_matrix}"}
